<?php
require_once __DIR__ . '/../bootstrap.php'; require_admin();$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){set_flash('error','Mã đơn hàng không hợp lệ.');header('Location: '.admin_url('orders/index.php'));exit;}$st=$conn->prepare('SELECT o.*,u.full_name,u.email FROM orders o LEFT JOIN users u ON u.id=o.user_id WHERE o.id=?');$st->execute([$id]);$order=$st->fetch(PDO::FETCH_ASSOC);if(!$order){set_flash('error','Không tìm thấy đơn hàng.');header('Location: '.admin_url('orders/index.php'));exit;}$st=$conn->prepare('SELECT oi.quantity,oi.price,p.name,p.image,p.brand FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?');$st->execute([$id]);$items=$st->fetchAll(PDO::FETCH_ASSOC);$labels=['pending'=>'Chờ xử lý','processing'=>'Đang xử lý','completed'=>'Hoàn thành','cancelled'=>'Đã hủy'];$payments=['cod'=>'Thanh toán khi nhận hàng','bank_transfer'=>'Chuyển khoản ngân hàng'];
admin_header('Chi tiết đơn hàng #'.$id); ?>
<div class="toolbar"><a class="btn btn-outline" href="<?= h(admin_url('orders/index.php')) ?>">← Quay lại danh sách</a><span class="badge badge-<?= h($order['status']) ?>"><?= h($labels[$order['status']]??$order['status']) ?></span></div><div class="detail-grid"><section class="card"><h2>Thông tin khách hàng</h2><div class="detail-item"><small>Họ tên</small><?= h($order['full_name']??'Tài khoản đã xóa') ?></div><div class="detail-item"><small>Email</small><?= h($order['email']??'') ?></div><div class="detail-item"><small>Số điện thoại</small><?= h($order['phone']) ?></div><div class="detail-item"><small>Địa chỉ giao hàng</small><?= nl2br(h($order['shipping_address'])) ?></div></section><section class="card"><h2>Thông tin đơn hàng</h2><div class="detail-item"><small>Mã đơn</small>#<?= (int)$order['id'] ?></div><div class="detail-item"><small>Ngày tạo</small><?= h($order['created_at']) ?></div><div class="detail-item"><small>Phương thức thanh toán</small><?= h($payments[$order['payment_method']]??$order['payment_method']) ?></div><div class="detail-item"><small>Ghi chú</small><?= $order['note']?nl2br(h($order['note'])):'Không có' ?></div><form method="post" action="<?= h(admin_url('orders/update_status.php')) ?>" style="margin-top:18px"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$order['id'] ?>"><div class="form-group"><label for="status">Cập nhật trạng thái</label><select class="form-control" id="status" name="status"><?php foreach($labels as $key=>$label): ?><option value="<?= h($key) ?>" <?= $order['status']===$key?'selected':'' ?>><?= h($label) ?></option><?php endforeach; ?></select></div><button class="btn" type="submit">Cập nhật trạng thái</button></form></section></div><section class="card"><h2>Sản phẩm trong đơn</h2><div class="table-wrap"><table><thead><tr><th>Sản phẩm</th><th>Đơn giá</th><th>Số lượng</th><th>Thành tiền</th></tr></thead><tbody><?php $subtotal=0; if(!$items): ?><tr><td colspan="4" class="empty">Không có chi tiết sản phẩm hoặc sản phẩm đã bị xóa.</td></tr><?php else: foreach($items as $item): $line=(float)$item['price']*(int)$item['quantity'];$subtotal+=$line; ?><tr><td><?= h($item['name']??'Sản phẩm không còn tồn tại') ?><?php if($item['brand']): ?><div class="text-muted"><?= h($item['brand']) ?></div><?php endif; ?></td><td><?= h(money($item['price'])) ?></td><td><?= (int)$item['quantity'] ?></td><td><?= h(money($line)) ?></td></tr><?php endforeach; endif; ?></tbody><tfoot><tr><th colspan="3" style="text-align:right">Tổng đơn hàng</th><th><?= h(money($order['total_amount'])) ?></th></tr></tfoot></table></div></section><?php admin_footer(); ?>
